using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Windows.Forms;
namespace Astera {
public sealed class CustomGame {public string Id=Guid.NewGuid().ToString("N"),Name="",Executable="",Background="",Character="";}
sealed class LibraryEntry {internal int Kind;internal string Name;internal CustomGame Custom;public override string ToString(){return Custom==null?Name:Custom.Name;}}
static class CustomGames {
    internal static string Validate(string path){if(String.IsNullOrWhiteSpace(path)||!Path.GetExtension(path).Equals(".exe",StringComparison.OrdinalIgnoreCase))throw new IOException("Choose a Windows EXE.");path=Path.GetFullPath(path);using(var stream=File.OpenRead(path))using(var reader=new BinaryReader(stream)){if(stream.Length<64||reader.ReadUInt16()!=0x5a4d)throw new IOException("This file is not a Windows executable.");stream.Position=60;int offset=reader.ReadInt32();if(offset<64||offset>stream.Length-4)throw new IOException("This EXE has an invalid header.");stream.Position=offset;if(reader.ReadUInt32()!=0x4550)throw new IOException("This file is not a Windows executable.");}return path;}
    internal static void Set(List<CustomGame> games,CustomGame item,string name,string path){path=Validate(path);name=(name??"").Trim();if(name.Length==0||name.Length>100||name.Any(Char.IsControl))throw new IOException("Give the game a name of 1–100 characters.");if(games.Any(g=>g!=item&&String.Equals(Path.GetFullPath(g.Executable),path,StringComparison.OrdinalIgnoreCase)))throw new IOException("That EXE is already in your library.");item.Name=name;item.Executable=path;}
    internal static ProcessStartInfo StartInfo(CustomGame game){var path=Validate(game.Executable);return new ProcessStartInfo(path){WorkingDirectory=Path.GetDirectoryName(path),UseShellExecute=true};}
}
sealed partial class LibraryForm {
    CustomGame CurrentCustom {get{var row=games.SelectedItem as LibraryEntry;return row==null?null:row.Custom;}}
    bool IsCustomGame {get{return CurrentCustom!=null;}}
    // Identity is independent of the alphabetic display position.
    int GameKind {get{var row=games.SelectedItem as LibraryEntry;return row==null?-1:row.Kind;}set{for(int i=0;i<games.Items.Count;i++)if(((LibraryEntry)games.Items[i]).Kind==value){games.SelectedIndex=i;return;}}}
    void ReloadGames(CustomGame selected){if(store.Settings.CustomGames==null)store.Settings.CustomGames=new List<CustomGame>();var rows=new List<LibraryEntry>{new LibraryEntry{Kind=0,Name="Minecraft²"},new LibraryEntry{Kind=1,Name="Star Dash"},new LibraryEntry{Kind=2,Name="FTL: Multiverse"}};rows.AddRange(store.Settings.CustomGames.Where(g=>g!=null).Select(g=>new LibraryEntry{Kind=3,Custom=g}));games.BeginUpdate();try{games.Items.Clear();foreach(var row in rows.OrderBy(r=>r.ToString(),StringComparer.OrdinalIgnoreCase).ThenBy(r=>r.Custom==null?"":r.Custom.Id,StringComparer.Ordinal))games.Items.Add(row);if(selected!=null)games.SelectedItem=games.Items.Cast<LibraryEntry>().First(r=>r.Custom==selected);}finally{games.EndUpdate();}}
    void AddCustomGame(){if(busy)return;using(var picker=new OpenFileDialog{Title="Add a game",Filter="Windows games (*.exe)|*.exe",CheckFileExists=true}){if(picker.ShowDialog(this)!=DialogResult.OK)return;var entry=new CustomGame{Name=Path.GetFileNameWithoutExtension(picker.FileName),Executable=picker.FileName};if(!EditCustomDialog(entry,true))return;}}
    void EditCustomGame(){if(CurrentCustom!=null)EditCustomDialog(CurrentCustom,false);}
    bool EditCustomDialog(CustomGame entry,bool adding){using(var dialog=new Form{Text=adding?"Add game":"Game settings",Size=new Size(610,270),StartPosition=FormStartPosition.CenterParent,FormBorderStyle=FormBorderStyle.FixedDialog,MaximizeBox=false,MinimizeBox=false,BackColor=Base,ForeColor=Color.White,Font=Font}){
        var name=new TextBox{Text=entry.Name,Left=20,Top=46,Width=550,MaxLength=100};var path=new TextBox{Text=entry.Executable,Left=20,Top=107,Width=430};var choose=Button("Browse…",delegate{using(var picker=new OpenFileDialog{Filter="Windows games (*.exe)|*.exe"})if(picker.ShowDialog(dialog)==DialogResult.OK)path.Text=picker.FileName;});choose.SetBounds(460,103,110,34);
        var save=Button(adding?"Add game":"Save",delegate{try{CustomGames.Set(store.Settings.CustomGames,entry,name.Text,path.Text);if(adding)store.Settings.CustomGames.Add(entry);store.Save();ReloadGames(entry);RefreshView();dialog.DialogResult=DialogResult.OK;}catch(Exception error){MessageBox.Show(dialog,error.Message,"Game settings");}});save.SetBounds(430,171,140,38);
        var remove=Button("Remove from library",delegate{if(MessageBox.Show(dialog,"Remove this entry from Astera? Your game files will stay where they are.","Remove game",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;store.Settings.CustomGames.Remove(entry);store.Save();ReloadGames(null);GameKind=0;dialog.DialogResult=DialogResult.OK;});remove.SetBounds(20,171,220,38);remove.Visible=!adding;
        dialog.Controls.AddRange(new Control[]{new Label{Text="Game name",Left=20,Top=19,AutoSize=true},name,new Label{Text="Game EXE",Left=20,Top=82,AutoSize=true},path,choose,save,remove});dialog.AcceptButton=save;return dialog.ShowDialog(this)==DialogResult.OK;}}
    void LaunchCustomGame(){try{Process.Start(CustomGames.StartInfo(CurrentCustom));}catch(Exception error){MessageBox.Show(this,error.Message+"\n\nCheck this game's EXE in Game settings.","Could not start game");}}
    void RefreshCustomView(){var game=CurrentCustom;appUpdateIcon.Enabled=!busy&&!checkingApp;banner.Game="custom";play.Text="PLAY";((AsteraButton)play).Symbol=ButtonSymbol.Play;play.Enabled=!busy&&File.Exists(game.Executable);check.Enabled=download.Enabled=install.Enabled=restore.Enabled=cancel.Enabled=false;settings.Enabled=games.Enabled=!busy;status.Text=File.Exists(game.Executable)?"Ready to play":"EXE not found";status.ForeColor=Color.White;profileLabel.Text=game.Executable;releaseLabel.Text="Added to your library";notes.Text="No patch notes available yet.";UpdateCustomLayout();games.Invalidate();}
    void UpdateCustomLayout(){var game=CurrentCustom;if(minecraftSkinChoice!=null)minecraftSkinChoice.Visible=false;heroTitle.Text=game.Name;heroSubtitle.Text="Your library. Ready when you are.";banner.Artwork(game.Background,game.Character);banner.LiveSkin(null);installationPath.Text=GameFolder();openFolder.Enabled=!busy&&Directory.Exists(GameFolder());chooseBackground.Enabled=chooseCharacter.Enabled=!busy;artLabel.Text=String.IsNullOrEmpty(game.Background)?"Choose your game artwork":Path.GetFileName(game.Background);string key="custom:"+game.Id+":"+game.Background;if(previewArtwork!=key){previewArtwork=key;var old=artPreview.Image;previewScene.Artwork=null;artPreview.Image=null;try{if(!String.IsNullOrEmpty(game.Background))artPreview.Image=Banner.ReadArtwork(game.Background);}catch{}previewScene.Artwork=artPreview.Image;if(old!=null)old.Dispose();previewScene.Invalidate();}}
}
}
